--[[
    Project: Hoverly Script (LT2 Complete Teleports Edition)
        Description: WindUI Hub with Full LT2 Teleports, Region Tree ESP, Fullbright & AutoFarm
        ]]

        -- Load WindUI Library safely
        local success, WindUI = pcall(function()
            return loadstring(game:HttpGet("https://raw.githubusercontent.com/Footagesus/WindUI/main/dist/main.lua"))()
            end)

            if not success or not WindUI then
                warn("WindUI failed to load.")
                    return
                    end

                    -- Create Main Window
                    local Window = WindUI:CreateWindow({
                        Title = "Hoverly Script | Lumber Tycoon 2",
                            Icon = "axe",
                                Author = "Hoverly Development",
                                    Folder = "HoverlyLT2Config",
                                        Theme = "Dark",
                                            Size = UDim2.new(0, 560, 0, 420),
                                                Transparent = false,
                                                    HasOutline = true,
                                                    })

                                                    -- Services
                                                    local players = game:GetService("Players")
                                                    local localPlayer = players.LocalPlayer
                                                    local lighting = game:GetService("Lighting")
                                                    local workspace = game:GetService("Workspace")
                                                    local runService = game:GetService("RunService")

                                                    -- Globals
                                                    _G.AutoFarmWood = false
                                                    _G.TreeESPEnabled = false
                                                    _G.SelectedWoodType = "Oak"
                                                    local espHighlights = {}

                                                    -- ==================== TABS ====================
                                                    local MainTab = Window:Tab({ Title = "Main", Icon = "home" })
                                                    local FarmTab = Window:Tab({ Title = "AutoFarm", Icon = "cpu" })
                                                    local TeleportTab = Window:Tab({ Title = "Teleports", Icon = "map-pin" })
                                                    local VisualsTab = Window:Tab({ Title = "Visuals", Icon = "eye" })
                                                    local PlayerTab = Window:Tab({ Title = "Player", Icon = "user" })
                                                    local SettingsTab = Window:Tab({ Title = "Settings", Icon = "settings" })

                                                    -- ==================== MAIN TAB ====================
                                                    MainTab:Button({
                                                        Title = "Welcome to LT2 Hub",
                                                            Desc = "Hoverly Script successfully loaded!",
                                                                Callback = function()
                                                                        WindUI:Notify({
                                                                                    Title = "Hoverly Script",
                                                                                                Content = "All locations loaded successfully!",
                                                                                                            Duration = 3
                                                                                                                    })
                                                                                                                        end
                                                                                                                        })

                                                                                                                        -- ==================== AUTOFARM TAB ====================
                                                                                                                        FarmTab:Toggle({
                                                                                                                            Title = "Auto Farm Wood (Smart Delivery)",
                                                                                                                                Desc = "Takes wood pieces, delivers to Wood Buyer & sells",
                                                                                                                                    Value = false,
                                                                                                                                        Callback = function(state)
                                                                                                                                                _G.AutoFarmWood = state
                                                                                                                                                        if state then
                                                                                                                                                                    WindUI:Notify({ Title = "Auto Farm", Content = "Auto Farm started!", Duration = 2 })
                                                                                                                                                                                
                                                                                                                                                                                            task.spawn(function()
                                                                                                                                                                                                            while _G.AutoFarmWood do
                                                                                                                                                                                                                                task.wait(0.5)
                                                                                                                                                                                                                                                    pcall(function()
                                                                                                                                                                                                                                                                            local char = localPlayer.Character
                                                                                                                                                                                                                                                                                                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                                                                                                                                                                                                                                                                                                                            if not hrp then return end

                                                                                                                                                                                                                                                                                                                                                    for _, model in ipairs(workspace:GetChildren()) do
                                                                                                                                                                                                                                                                                                                                                                                if not _G.AutoFarmWood then break end
                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                        if model:FindFirstChild("WoodSection") then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for _, part in ipairs(model:GetChildren()) do
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if part.Name == "WoodSection" and part:IsA("BasePart") then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    local buyerPos = CFrame.new(315, 5, 75)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            part.CFrame = buyerPos + Vector3.new(math.random(-3, 3), 2, math.random(-3, 3))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    task.wait(0.2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            break
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        WindUI:Notify({ Title = "Auto Farm", Content = "Auto Farm stopped.", Duration = 2 })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    })

